		let settled = false;
		const onAbort = () => {
			if (settled) return;
			settled = true;
			signal.removeEventListener("abort", onAbort);
			reject(
				signal.reason ?? new DOMException("Operation canceled", "AbortError"),
			);
		};
		signal.addEventListener("abort", onAbort, { once: true });
		void sleep(delayMs, signal).then(
			() => {
				if (settled) return;
				settled = true;
				signal.removeEventListener("abort", onAbort);
				resolve();
			},
			(error) => {
				if (settled) return;
				settled = true;
				signal.removeEventListener("abort", onAbort);
				reject(error);
			},
