			if (settled) return;
			settled = true;
			cleanup();
			resolve();
		};
		const rejectSleep = <T>(reason: T) => {
			if (settled) return;
			settled = true;
			cleanup();
			reject(reason);
		};
		const onAbort = () =>
			rejectSleep(
				signal?.reason ?? new DOMException("Operation canceled", "AbortError"),
			);
